#include <bits/stdc++.h>
using namespace std;

string removeKdigits(string num, int k) {
    string ans;  // used as the stack
    for (char c : num) {
        while (!ans.empty() && k > 0 && ans.back() > c) {
            ans.pop_back();
            --k;
        }
        ans.push_back(c);
    }
    ans.resize(ans.size() - k);  // remove leftover from the back
    int zeros = 0;
    while (zeros < (int)ans.size() && ans[zeros] == '0') ++zeros;
    ans = ans.substr(zeros);
    return ans.empty() ? "0" : ans;
}

